function resolveRelTargetFromRels(relsPath, target) {
    if (!target)
        return target;
    if (/^https?:/i.test(target))
        return target;
    if (target.startsWith('/'))
        return 'ppt' + target;
    if (target.startsWith('ppt/'))
        return target;
    const baseDir = relsPath.replace(/_rels\/[^/]*\.rels$/, '').replace(/[^/]+$/, '');
    const stack = [];
    for (const seg of (baseDir + target).split('/')) {
        if (seg === '' || seg === '.')
            continue;
        if (seg === '..')
            stack.pop();
        else
            stack.push(seg);
    }
    return stack.join('/');
}
async function orderSlidesBySldIdLst(zip, slideFiles) {
    try {
        const presFile = zip.file('ppt/presentation.xml');
        if (!presFile)
            return slideFiles;
        const presText = await presFile.async('string');
        const lstMatch = presText.match(/<p:sldIdLst>([\s\S]*?)<\/p:sldIdLst>/);
        if (!lstMatch)
            return slideFiles;
        const relIds = [];
        const sldIdRe = /<p:sldId\s+([^>]*?)\/>/g;
        let m;
        while ((m = sldIdRe.exec(lstMatch[1])) !== null) {
            const idMatch = m[1].match(/r:id="([^"]*)"/);
            if (idMatch)
                relIds.push(idMatch[1]);
        }
        if (!relIds.length)
            return slideFiles;
        const relMap = {};
        const relsFile = zip.file('ppt/_rels/presentation.xml.rels');
        if (relsFile) {
            const relsText = await relsFile.async('string');
            const relRe = /<Relationship\s+([^>]*?)\/?>/g;
            while ((m = relRe.exec(relsText)) !== null) {
                const id = (m[1].match(/Id="([^"]*)"/) || [])[1];
                const tgt = (m[1].match(/Target="([^"]*)"/) || [])[1];
                if (id && tgt)
                    relMap[id] = tgt.replace(/^(\.\.\/)+/, '').replace(/^ppt\//, '');
            }
        }
        const norm = (f) => f.replace(/^ppt\//, '').replace(/^\/+/, '');
        const byTarget = new Map();
        for (const f of slideFiles)
            byTarget.set(norm(f), f);
        const ordered = [];
        const seen = new Set();
        for (const rid of relIds) {
            const tgt = relMap[rid];
            if (!tgt)
                continue;
            const f = byTarget.get(norm('ppt/' + tgt));
            if (f && !seen.has(f)) {
                ordered.push(f);
                seen.add(f);
            }
        }
        for (const f of slideFiles)
            if (!seen.has(f))
                ordered.push(f);
        return ordered.length ? ordered : slideFiles;
    }
    catch {
        return slideFiles;
    }
}
